if (typeof type === 'string') {
	const nonCustomElement = type.indexOf(vnodeTypeNames.dash) === -1;
	normalizedProps = {};

	for (let i in props) {
		let value = props[i];

		if (
			this.isDom &&
			i === 'children' &&
			type === vnodeTypeNames.noscriptTag
		) {
			// Emulate React's behavior of not rendering the contents of noscript tags on the client.
			continue;
		} else if (i === 'value' && 'defaultValue' in props && value == null) {
			// Skip applying value if it is null/undefined and we already set
			// a default value
			continue;
		} else if (
			i === 'defaultValue' &&
			'value' in props &&
			props.value == null
		) {
			// `defaultValue` is treated as a fallback `value` when a value prop is present but null/undefined.
			// `defaultValue` for Elements with no value prop is the same as the DOM defaultValue property.
			i = 'value';
		} else if (i === 'download' && value === true) {
			// Calling `setAttribute` with a truthy value will lead to it being
			// passed as a stringified value, e.g. `download="true"`. React
			// converts it to an empty string instead, otherwise the attribute
			// value will be used as the file name and the file will be called
			// "true" upon downloading it.
			value = '';
		} else if (eventAliasRules.doubleClick.test(i)) {
			i = 'ondblclick';
		} else if (
			eventAliasRules.changeEvent.test(i + type) &&
			!propAliasRules.inputTypePattern.test(props.type)
		) {
			i = 'oninput';
		} else if (eventAliasRules.focusEvent.test(i)) {
			i = 'onfocusin';
		} else if (/^onblur$/i.test(i)) {
			i = 'onfocusout';
		} else if (/^on(Ani|Tra|Tou|BeforeInp|Compo)/.test(i)) {
			i = i.toLowerCase();
		} else if (nonCustomElement && propAliasRules.camelProps.test(i)) {
			i = i.replace(/[A-Z0-9]/, '-$&').toLowerCase();
		} else if (value === null) {
			value = undefined;
		}

		normalizedProps[i] = value;
	}

